// @generated by auto-design from design.config.ts. The Pace motion profile (still).
// Use with Motion (import { motion } from "motion/react") or element.animate(). Durations are in seconds.

export const duration = { fast: 0.1, base: 0.15, slow: 0.2, reveal: 0.2 } as const;

export const ease = { out: [0.25, 1, 0.5, 1], inOut: [0.65, 0, 0.35, 1] } as const;

/** The same curves as CSS strings, for element.animate() and inline styles. */
export const css = {
  easeOut: "cubic-bezier(0.25, 1, 0.5, 1)",
  easeInOut: "cubic-bezier(0.65, 0, 0.35, 1)",
  spring: "cubic-bezier(0.25, 1, 0.5, 1)",
} as const;

/** For drag, layout changes and anything that follows the pointer. This profile has none: use ease.out. */
export const spring = null;

/** Entering elements: a fade. Never from scale 0. */
export const enter = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  transition: { duration: duration.base, ease: ease.out },
} as const;

export const exit = {
  opacity: 0,
  transition: { duration: duration.fast, ease: ease.inOut },
} as const;

/** Content arriving as it scrolls into view: data, sections, text. Never a response to a press. */
export const reveal = {
  initial: { opacity: 0 },
  whileInView: { opacity: 1 },
  viewport: { once: true, amount: 0.4 },
  transition: { duration: duration.reveal, ease: ease.out },
} as const;

/** Seconds between items in a staggered reveal. */
export const stagger = 0;

/** Brand animation timing (launch films, social posts): slower and larger than product UI. */
export const brand = { beat: 0.56, stagger: 0.14, hold: 1.4, travel: 0 } as const;

/** Whether loops (spinners aside) may move at all. */
export const ambient = false;
